    confirm=read(HERE/'CONFIRMATORY_RESULTS.json');dev=read(HERE/'DEVELOPMENT_RESULTS.json');decision=read(HERE/'MAIN_METHOD_SELECTION.json');budget=read(HERE/'NEW_EVAL_BUDGET.json');head=read(HERE/'SELECTABLE_SPACE.json');e=confirm['endpoints'];summary=confirm['reports']['combined']['type_equal'];m=summary['methods'];primary=confirm['primary_method'];self_primary=primary=='self_schedule'
    switch=e['endpoint2']['switch_distributions'];effective={t:sum(switch[t]['self_schedule']['non_diagonal_counts'].values()) for t in switch};non500=sum(sum(n for t,n in switch[k]['self_schedule']['non_diagonal_counts'].items() if t!='500') for k in switch)
