        early=', '.join(f'{a:.4f}' for a in v['eta_early_quantiles'][2]);late=', '.join(f'{a:.4f}' for a in v['eta_late_quantiles'][2]);cosine=v['direction_cosine_quantiles'][2] if v['direction_cosine_quantiles'] is not None else None;actual=executed[kind]['late_eta_executed_fraction_among_non_diagonal'];lines.append(f'| {TYPE_NAMES.get(kind,kind)} | ({early}) | ({late}) | {cosine:.4f} | {100*actual:.2f}% |')
